import pathlib,json,copy,urllib.parse,math,re
def unique(pairs):
 d={}
 for k,v in pairs:
  if k in d:raise ValueError('duplicate key: '+k)
  d[k]=v
 return d
def load(name):return json.loads(pathlib.Path(name).read_text(encoding='utf-8'),object_pairs_hook=unique)

BASE={'dashboard.json': {'id': None, 'uid': 'service-main', 'title': 'Service', 'schemaVersion': 39, 'version': 3, 'timezone': 'utc', 'time': {'from': 'now-6h', 'to': 'now'}, 'templating': {'list': []}, 'panels': [{'id': 1, 'title': 'Requests', 'type': 'table', 'datasource': {'type': 'grafana-testdata-datasource', 'uid': 'fixtures'}, 'gridPos': {'x': 0, 'y': 0, 'w': 12, 'h': 8}, 'targets': [{'refId': 'A', 'datasource': {'type': 'grafana-testdata-datasource', 'uid': 'fixtures'}, 'scenarioId': 'raw_frame', 'rawFrameContent': '[{"name": "A", "fields": [{"name": "Time_seconds", "type": "string", "values": ["1700000000", "1700000060"]}, {"name": "latency_ms", "type": "number", "values": [12, 20]}]}, {"name": "B", "fields": [{"name": "Clock", "type": "time", "values": [1700000000000, 1700000060000]}, {"name": "errors", "type": "number", "values": [1, 0]}]}]'}], 'fieldConfig': {'defaults': {}, 'overrides': []}, 'options': {}, 'transformations': [{'id': 'joinByField', 'options': {'byField': 'Clock', 'mode': 'outerTabular'}}]}], 'links': []}, 'expected-table.json': []}
d=load('dashboard.json');base=BASE['dashboard.json'];assert len(d['panels'])==1
assert {k:v for k,v in d.items() if k!='panels'}=={k:v for k,v in base.items() if k!='panels'}
p=d['panels'][0];assert {k:v for k,v in p.items() if k!='transformations'}=={k:v for k,v in base['panels'][0].items() if k!='transformations'}
ts=p['transformations'];assert len(ts)==3
assert ts[0]=={'id':'convertFieldType','options':{'conversions':[{'targetField':'Time_seconds','destinationType':'time','dateFormat':'X'}]}}
assert ts[1]['id']=='renameByRegex';o=ts[1]['options'];rx=re.compile(o['regex'])
for name,want in [('Time_seconds','Clock'),('errors','errors'),('latency_ms','latency_ms'),('OtherTime_seconds','OtherTime_seconds')]:assert rx.sub(o['renamePattern'],name)==want
assert ts[2]=={'id':'joinByField','options':{'byField':'Clock','mode':'outerTabular'}}
